        return (switch (fmt) {
.jpeg => jpeg.decode(bytes, max_pixels, hint),
.png => png.decode(bytes, max_pixels),
.webp => webp.decode(bytes, max_pixels),
.heic, .avif, .tiff => (blk_catch_0: { break :blk_catch_0 ((decodeViaSystem(bytes, max_pixels)) catch |e| { _ = &e; if ((e == error.BackendUnavailable)) {
