.gif => (blk_catch_2: { break :blk_catch_2 ((decodeViaSystem(bytes, max_pixels)) catch |e| { _ = &e; if ((e == error.BackendUnavailable)) {
            return gif.decode(bytes, max_pixels);
        }
        return e; }); }),
